import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.BTLSZHNB.js";const f=JSON.parse('{"title":"takoform_interface","description":"Reads one exact runtime interface declaration.","frontmatter":{"page_title":"takoform_interface Data Source - takoform","subcategory":"Service Forms","description":"Reads one exact runtime interface declaration."},"headers":[],"relativePath":"docs/data-sources/interface.md","filePath":"docs/data-sources/interface.md"}'),i={name:"docs/data-sources/interface.md"};function n(s,e,c,d,l,u){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="takoform-interface" tabindex="-1">takoform_interface <a class="header-anchor" href="#takoform-interface" aria-label="Permalink to &quot;takoform_interface&quot;">​</a></h1><p>Reads one runtime interface declaration from a conforming host. See the <a href="../../examples/data-sources/takoform_interface/data-source.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required) — declared interface name.</li><li><code>version</code> (String, optional) — exact author-defined version. Omit it only when the visible name has one version; multiple versions fail closed.</li><li><code>resource_kind</code> and <code>resource_name</code> (String, optional as a pair) — portable Resource instance exposing the descriptor. Omit both only when one visible Resource matches; multiple instances fail closed.</li><li><code>space</code> (String, optional) — Space to read from. An explicit value wins; otherwise the provider default is required. The read fails before contacting the host when neither supplies a non-empty Space.</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>version</code> — exact resolved version (also usable as the optional selector).</li><li><code>resource_kind</code> / <code>resource_name</code> — exact resolved portable Resource reference (also usable as paired optional selectors).</li><li><code>document_json</code> — exact non-secret declaration document as JSON.</li><li><code>values_json</code> — resolved public values as JSON.</li><li><code>resource_uri</code> — host-resolved credential-free HTTPS endpoint when the Interface has one. This is runtime location, not portable Resource state or an authorization grant.</li><li><code>form_kind</code> — declaring Form kind when the host reports it.</li></ul><p>This data source grants nothing. It never reads or creates bindings, permissions, tokens, credentials, or lifecycle state. The descriptor comes from a Form Definition; there is no portable <code>takoform_interface</code> resource or standalone Interface write path. The host owns the resulting Interface record, bindings, write fencing, authorization, and lifecycle. Host responses that violate the portable data-only field policy are rejected before <code>document_json</code> or <code>values_json</code> enters non-sensitive Terraform state. No host Interface id is exposed. The host must advertise <code>features.interface_declarations</code>.</p><p>The provider sends the effective Space on every Interface list or exact read and stores that exact value in data source state. A host scopes visibility and ambiguity checks to the requested Space; it cannot silently select another one.</p><p><code>resource_uri</code> is a normal computed Terraform value, so a module can pass it to another resource, local, or output. It remains <code>null</code> when the host does not report an endpoint. Opaque Interface-specific values remain available through <code>jsondecode(values_json)</code>.</p>',9)])])}const p=o(i,[["render",n]]);export{f as __pageData,p as default};
